window.__cs = async () => { const M = window.moire, C = M.cells, d = M.gpu.device, n = C.count, F = 92;
  const buf = d.createBuffer({ size: n * F * 4, usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST });
  const e = d.createCommandEncoder(); e.copyBufferToBuffer(C.cellBuf, 0, buf, 0, n * F * 4); d.queue.submit([e.finish()]);
  await buf.mapAsync(GPUMapMode.READ); const f = new Float32Array(buf.getMappedRange().slice(0)); buf.unmap(); buf.destroy();
  const u = new Uint32Array(f.buffer); let a = 0, bat = 0, out = 0, r = 0, low = 0;
  for (let i = 0; i < n; i++) { if (!(u[i*F+9] & 1)) continue; a++; bat += f[i*F+16]; r += f[i*F+4]; if (f[i*F+16] < 0.02) low++;
    if (f[i*F] < 0 || f[i*F+1] < 0 || f[i*F] > M.dish.W || f[i*F+1] > M.dish.H) out++; }
  return { t: M.time(), alive: a, bat: bat / a, r: r / a / C.R, low, out, W: M.dish.W }; };
return 'ok';

